// Headless tests have no wasm client: this installs `Module._d2_client_unit_sound_event_row` from a table of the
// export's own output (unit-sound-event-row.fixture.json, generated by running unit_sound_event_row.cpp natively over
// every event 0..255 for the player classes, 271 and an unlisted class; the sentinels 1000001 / 1000002 stand for the
// taunt and skill-start rows the caller passes).
import { readFileSync } from 'node:fs';
const fx = JSON.parse(readFileSync(new URL('./unit-sound-event-row.fixture.json', import.meta.url), 'utf8'));
const KNOWN = new Set([0, 1, 2, 3, 4, 5, 6, 271]);
export function installUnitSoundFixture() {
  const fn = (unitType, classId, event, isLocal, taunt, skillStart) => {
    if ((event & 0xffff) > 255) return -1;
    const ut = unitType === 0 ? 0 : 1, c = KNOWN.has(classId) ? classId : 999;
    const r = (isLocal ? fx.B : fx.A)[`${ut}:${c}`][event & 0xff];
    // the sentinels carry the export's own "the passed row, when positive" rule
    return r === 1000001 ? (taunt > 0 ? taunt : -1) : r === 1000002 ? (skillStart > 0 ? skillStart : -1) : r;
  };
  globalThis.Module = Object.assign(globalThis.Module || {}, { _d2_client_unit_sound_event_row: fn });
}
